  const gr = g.createRadialGradient(64, 32, 4, 64, 32, 62); gr.addColorStop(0, 'rgba(255,150,80,0.9)'); gr.addColorStop(0.45, 'rgba(255,110,50,0.45)'); gr.addColorStop(1, 'rgba(255,90,40,0)');
