  canvas.addEventListener('pointerdown', (e) => { if (!D.on) return; if (e.pointerType === 'mouse' && e.button !== 0) return; D.ptrT = e.timeStamp || performance.now(); D.ptrPend = true; if (e.pointerType === 'mouse') aimFromMouse(e); });
