    try { if (window.__radio && __radio.duckTo) __radio.duckTo(1); } catch (e) {}
    if (D.saved) { OUT_U.fogC.value.copy(D.saved.fogC); OUT_U.fogN.value = D.saved.fogN; OUT_U.fogF.value = D.saved.fogF; }
