    S.shake = Math.max(0, (S.shake || 0) - dt * 1.8); const sh = S.shake * 0.35;
    cam.position.set(camP.x + rnd(-sh, sh), camP.y + rnd(-sh, sh), camP.z + rnd(-sh, sh)); cam.lookAt(camL);
