      const { f, r } = lockFrame(st); const want = new THREE.Vector3().addScaledVector(r, I.mx).addScaledVector(f, I.my); want.y = (I.up ? 1 : 0) - (I.down ? 1 : 0);
      want.multiplyScalar(5.2); if (want.y) want.y *= 0.8;
