  function floorTex() { return canvasTex(256, 256, (g, w, h) => { for (let y = 0; y < 8; y++) for (let x = 0; x < 8; x++) { g.fillStyle = (x + y) % 2 ? '#d8d0c0' : '#7a3a2a'; g.fillRect(x * 32, y * 32, 32, 32); } }, 256); }
