    if (mode === 'waddle') { aLx = aRx = -0.3 + Math.sin(st.outT * 7) * 0.3; hY = 0; hX = 0.1; }
    if (mode === 'idle') { aRx = -1.3; hY = Math.sin(t * 0.8) * 0.3; }
