    const tk = new THREE.Mesh(new THREE.PlaneGeometry(2.4, 0.42), new THREE.MeshBasicMaterial({ map: ticketTex(), fog: false })); tk.position.set(-4.5, 2.7, 10.45); tk.rotation.y = Math.PI; sc.add(tk);
