    if (st.bankT >= 0) { V.lerp(V2.clone().set(st.hx, 3, st.hz - 4), 0.45); }
    if (st.ms === 'ko') { V.set(st.sx * 0.5, 7.5, st.sz - 9); V2.set(st.sx, 0, st.sz); }
