    P.camP.lerp(V, 1 - Math.exp(-6 * dt / Math.max(0.2, st.ts))); P.camL.lerp(V2, 1 - Math.exp(-6 * dt / Math.max(0.2, st.ts))); P.cam.position.copy(P.camP); P.cam.lookAt(P.camL);
