  const L = LANDMARKS.find((l) => l.id === 'pendry'); if (L && L.boss) DUELS.addTrigger('poolshark', L, L.boss.x, L.boss.z, L.boss.x + 2.8, L.boss.z + 0.1, '#39d8ff');
