    const Hd = K();
    Hd.add(G.cyl(0.16, 0.22, 0.6, 10), WH, 0, 0.2, 0, 0.15, 0, 0).add(G.sph(0.32, 14, 10), WH, 0, 0.6, 0.05, 0, 0, 0, 1, 1.05, 1.05)
