    for (let i = 0; i < 4; i++) Hd.add(G.cyl(0.05, 0.05, 0.14, 8), ['#7ad0ff', '#ff9ac8', '#a8f080', '#ffd23c'][i], -0.24 + i * 0.16, 0.86, 0.22, 0, 0, Math.PI / 2); // curlers
