    C.deckL = new THREE.PointLight('#ffb070', 10, 10, 1.6); C.deckL.position.set(-2.6, 3.0, 1.6); sc.add(C.deckL); // a ship's lamp over the capstan (warm, Harold's side)
    buildArena(sc); buildPhantoms(sc);
